INSERT INTO demo_review_items VALUES
('G40_PAST_SIMPLE', 'WRITING', 'DEMO-PS-G40_PAST_SIMPLE-2', 'Luyện thêm: Irregular and regular verbs', 1, 'MULTIPLE_CHOICE', 'Yesterday we ______ to the cinema.', 'went', 'go', 'goed', 'A', NULL, 'Go is irregular: the past simple is went.', NULL, 'EASY'),
('G40_PAST_SIMPLE', 'WRITING', 'DEMO-PS-G40_PAST_SIMPLE-2', 'Luyện thêm: Irregular and regular verbs', 2, 'MULTIPLE_CHOICE', 'She ______ the window because it was cold.', 'closes', 'closed', 'closeed', 'B', NULL, 'Regular verbs add -ed (close + d).', NULL, 'EASY'),
('G40_PAST_SIMPLE', 'WRITING', 'DEMO-PS-G40_PAST_SIMPLE-2', 'Luyện thêm: Irregular and regular verbs', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: I ______ (buy) a new phone last week.', NULL, NULL, NULL, NULL, ARRAY['bought'], 'Buy is irregular: the past simple is bought.', NULL, 'EASY'),
('G40_PAST_SIMPLE', 'WRITING', 'DEMO-PS-G40_PAST_SIMPLE-3', 'Luyện thêm: Past events', 1, 'MULTIPLE_CHOICE', 'They ______ football in the park on Sunday.', 'play', 'plaied', 'played', 'C', NULL, 'Play is regular: played.', NULL, 'EASY'),
('G40_PAST_SIMPLE', 'WRITING', 'DEMO-PS-G40_PAST_SIMPLE-3', 'Luyện thêm: Past events', 2, 'MULTIPLE_CHOICE', 'He ______ a long email to his boss yesterday.', 'wrote', 'writed', 'written', 'A', NULL, 'Write is irregular: the past simple is wrote. Written is the past participle.', NULL, 'EASY'),
('G40_PAST_SIMPLE', 'WRITING', 'DEMO-PS-G40_PAST_SIMPLE-3', 'Luyện thêm: Past events', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: We ______ (see) a good film last night.', NULL, NULL, NULL, NULL, ARRAY['saw'], 'See is irregular: the past simple is saw.', NULL, 'EASY'),
('G40_QUESTIONS_NEGATIVES', 'WRITING', 'DEMO-PS-G40_QUESTIONS_NEGATIVES-2', 'Luyện thêm: Present questions and negatives', 1, 'MULTIPLE_CHOICE', 'Which question is correct?', 'Does she works here?', 'Does she work here?', 'Do she work here?', 'B', NULL, 'With she, use does + the base verb.', NULL, 'EASY'),
('G40_QUESTIONS_NEGATIVES', 'WRITING', 'DEMO-PS-G40_QUESTIONS_NEGATIVES-2', 'Luyện thêm: Present questions and negatives', 2, 'MULTIPLE_CHOICE', 'He ______ like fish.', 'don''t', 'isn''t', 'doesn''t', 'C', NULL, 'With he, the negative is doesn''t + the base verb.', NULL, 'EASY'),
('G40_QUESTIONS_NEGATIVES', 'WRITING', 'DEMO-PS-G40_QUESTIONS_NEGATIVES-2', 'Luyện thêm: Present questions and negatives', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: ______ they play tennis on Sundays?', NULL, NULL, NULL, NULL, ARRAY['do'], 'With they, questions start with do.', NULL, 'EASY'),
('G40_QUESTIONS_NEGATIVES', 'WRITING', 'DEMO-PS-G40_QUESTIONS_NEGATIVES-3', 'Luyện thêm: Past questions and negatives', 1, 'MULTIPLE_CHOICE', 'Which sentence is correct?', 'I didn''t see him.', 'I didn''t saw him.', 'I not see him.', 'A', NULL, 'After didn''t the verb stays in the base form: see.', NULL, 'EASY'),
('G40_QUESTIONS_NEGATIVES', 'WRITING', 'DEMO-PS-G40_QUESTIONS_NEGATIVES-3', 'Luyện thêm: Past questions and negatives', 2, 'MULTIPLE_CHOICE', '______ you finish the report yesterday?', 'Do', 'Did', 'Does', 'B', NULL, 'Yesterday is a past time, so the question starts with did.', NULL, 'EASY'),
('G40_QUESTIONS_NEGATIVES', 'WRITING', 'DEMO-PS-G40_QUESTIONS_NEGATIVES-3', 'Luyện thêm: Past questions and negatives', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: She ______ not eat meat. She is vegetarian.', NULL, NULL, NULL, NULL, ARRAY['does'], 'With she, the negative uses does not.', NULL, 'EASY'),
('G55_BASIC_SENTENCE_PATTERNS', 'WRITING', 'DEMO-PS-G55_BASIC_SENTENCE_PATTERNS-2', 'Luyện thêm: Word order in simple sentences', 1, 'MULTIPLE_CHOICE', 'Which sentence has the correct word order?', 'Plays she tennis on Saturdays.', 'She tennis plays on Saturdays.', 'She plays tennis on Saturdays.', 'C', NULL, 'English statements follow subject + verb + object, then place or time.', 'Chủ ngữ, động từ, rồi tân ngữ.', 'EASY'),
('G55_BASIC_SENTENCE_PATTERNS', 'WRITING', 'DEMO-PS-G55_BASIC_SENTENCE_PATTERNS-2', 'Luyện thêm: Word order in simple sentences', 2, 'MULTIPLE_CHOICE', 'Choose the correct negative sentence.', 'They do not live in London.', 'They not live in London.', 'They does not live in London.', 'A', NULL, 'Use do not (don''t) with they, followed by the base verb.', 'Với they dùng do not.', 'EASY'),
('G55_BASIC_SENTENCE_PATTERNS', 'WRITING', 'DEMO-PS-G55_BASIC_SENTENCE_PATTERNS-2', 'Luyện thêm: Word order in simple sentences', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: ______ you like coffee? (a yes/no question in the present)', NULL, NULL, NULL, NULL, ARRAY['do'], 'Present questions with you use do + subject + base verb.', 'Trợ động từ mở đầu câu hỏi.', 'EASY'),
('G55_BASIC_SENTENCE_PATTERNS', 'WRITING', 'DEMO-PS-G55_BASIC_SENTENCE_PATTERNS-3', 'Luyện thêm: Past tense patterns', 1, 'MULTIPLE_CHOICE', 'Which sentence is correct?', 'Did he finished the work?', 'Did he finish the work?', 'Finished he the work?', 'B', NULL, 'After did, the main verb stays in the base form: Did he finish...?', 'Sau did, động từ giữ nguyên dạng gốc.', 'EASY'),
('G55_BASIC_SENTENCE_PATTERNS', 'WRITING', 'DEMO-PS-G55_BASIC_SENTENCE_PATTERNS-3', 'Luyện thêm: Past tense patterns', 2, 'MULTIPLE_CHOICE', 'Choose the correct past negative sentence.', 'We not watched the match.', 'We did not watched the match.', 'We did not watch the match.', 'C', NULL, 'Past negative: did not + base verb.', 'did not đi với động từ nguyên mẫu.', 'EASY'),
('G55_BASIC_SENTENCE_PATTERNS', 'WRITING', 'DEMO-PS-G55_BASIC_SENTENCE_PATTERNS-3', 'Luyện thêm: Past tense patterns', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: Yesterday I ______ my homework before dinner. (do, past simple)', NULL, NULL, NULL, NULL, ARRAY['did'], 'The past simple of do is did.', 'Quá khứ của do.', 'EASY'),
('G55_COMPARISON', 'WRITING', 'DEMO-PS-G55_COMPARISON-2', 'Luyện thêm: Comparing people and things', 1, 'MULTIPLE_CHOICE', 'Tom is ______ than his brother.', 'taller', 'more tall', 'tallest', 'A', NULL, 'Short adjectives add -er in the comparative: taller.', NULL, 'EASY'),
('G55_COMPARISON', 'WRITING', 'DEMO-PS-G55_COMPARISON-2', 'Luyện thêm: Comparing people and things', 2, 'MULTIPLE_CHOICE', 'This phone is ______ expensive than that one.', 'least', 'less', 'fewer', 'B', NULL, 'Less + adjective compares two things; least is for three or more.', NULL, 'EASY'),
('G55_COMPARISON', 'WRITING', 'DEMO-PS-G55_COMPARISON-2', 'Luyện thêm: Comparing people and things', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: Of the three cities, Tokyo is the ______ (big).', NULL, NULL, NULL, NULL, ARRAY['biggest'], 'Superlatives for three or more: the + biggest.', NULL, 'EASY'),
('G55_COMPARISON', 'WRITING', 'DEMO-PS-G55_COMPARISON-3', 'Luyện thêm: Comparing figures', 1, 'MULTIPLE_CHOICE', 'Sales in 2020 were ______ in 2019.', 'more high that', 'as higher as', 'higher than', 'C', NULL, 'Comparative + than: higher than.', NULL, 'EASY'),
('G55_COMPARISON', 'WRITING', 'DEMO-PS-G55_COMPARISON-3', 'Luyện thêm: Comparing figures', 2, 'MULTIPLE_CHOICE', 'Bus tickets are not as expensive ______ train tickets.', 'as', 'than', 'like', 'A', NULL, 'not as + adjective + as.', NULL, 'EASY'),
('G55_COMPARISON', 'WRITING', 'DEMO-PS-G55_COMPARISON-3', 'Luyện thêm: Comparing figures', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: This road is much ______ (busy) than the old one.', NULL, NULL, NULL, NULL, ARRAY['busier'], 'Busy becomes busier: y changes to i before -er.', NULL, 'EASY'),
('G55_LINKING_WORDS', 'WRITING', 'DEMO-PS-G55_LINKING_WORDS-2', 'Luyện thêm: Contrast, result and reason', 1, 'MULTIPLE_CHOICE', 'I wanted to go out, ______ it was raining.', 'so', 'but', 'or', 'B', NULL, 'But joins two ideas that contrast.', NULL, 'EASY'),
('G55_LINKING_WORDS', 'WRITING', 'DEMO-PS-G55_LINKING_WORDS-2', 'Luyện thêm: Contrast, result and reason', 2, 'MULTIPLE_CHOICE', 'He studied hard, ______ he passed the exam.', 'but', 'or', 'so', 'C', NULL, 'So shows a result.', NULL, 'EASY'),
('G55_LINKING_WORDS', 'WRITING', 'DEMO-PS-G55_LINKING_WORDS-2', 'Luyện thêm: Contrast, result and reason', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: We stayed at home ______ it was too cold. (reason)', NULL, NULL, NULL, NULL, ARRAY['because', 'as', 'since'], 'Because, as and since all introduce a reason.', NULL, 'EASY'),
('G55_LINKING_WORDS', 'WRITING', 'DEMO-PS-G55_LINKING_WORDS-3', 'Luyện thêm: Time and concession', 1, 'MULTIPLE_CHOICE', '______ the traffic was heavy, we arrived on time.', 'Although', 'Because', 'So', 'A', NULL, 'Although introduces an unexpected contrast.', NULL, 'EASY'),
('G55_LINKING_WORDS', 'WRITING', 'DEMO-PS-G55_LINKING_WORDS-3', 'Luyện thêm: Time and concession', 2, 'MULTIPLE_CHOICE', 'First, mix the flour and eggs. ______, add the milk.', 'However', 'Then', 'Because', 'B', NULL, 'Then shows the next step in a sequence.', NULL, 'EASY'),
('G55_LINKING_WORDS', 'WRITING', 'DEMO-PS-G55_LINKING_WORDS-3', 'Luyện thêm: Time and concession', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: Cars are fast; ______, they are expensive to run. (contrast)', NULL, NULL, NULL, NULL, ARRAY['however'], 'However introduces a contrasting idea after a semicolon.', NULL, 'EASY'),
('G55_PASSIVE_VOICE', 'WRITING', 'DEMO-PS-G55_PASSIVE_VOICE-2', 'Luyện thêm: Forming the passive', 1, 'MULTIPLE_CHOICE', 'The bridge ______ in 1990.', 'built', 'is build', 'was built', 'C', NULL, 'Past passive: was/were + past participle.', NULL, 'EASY'),
('G55_PASSIVE_VOICE', 'WRITING', 'DEMO-PS-G55_PASSIVE_VOICE-2', 'Luyện thêm: Forming the passive', 2, 'MULTIPLE_CHOICE', 'English ______ in many countries.', 'is spoken', 'speaks', 'is speaking', 'A', NULL, 'Present passive: is/are + past participle.', NULL, 'EASY'),
('G55_PASSIVE_VOICE', 'WRITING', 'DEMO-PS-G55_PASSIVE_VOICE-2', 'Luyện thêm: Forming the passive', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: The cars are ______ (make) in Japan.', NULL, NULL, NULL, NULL, ARRAY['made'], 'Passive uses the past participle: made.', NULL, 'EASY'),
('G55_PASSIVE_VOICE', 'WRITING', 'DEMO-PS-G55_PASSIVE_VOICE-3', 'Luyện thêm: Active or passive?', 1, 'MULTIPLE_CHOICE', 'Which sentence is passive?', 'The manager wrote the report.', 'The report was written by the manager.', 'The manager is writing the report.', 'B', NULL, 'In a passive sentence the object comes first and the verb is was/were + past participle.', NULL, 'EASY'),
('G55_PASSIVE_VOICE', 'WRITING', 'DEMO-PS-G55_PASSIVE_VOICE-3', 'Luyện thêm: Active or passive?', 2, 'MULTIPLE_CHOICE', 'Rice ______ by farmers in warm countries.', 'grows', 'is growing', 'is grown', 'C', NULL, 'Farmers grow rice, so with "by farmers" we need the passive: is grown.', NULL, 'EASY'),
('G55_PASSIVE_VOICE', 'WRITING', 'DEMO-PS-G55_PASSIVE_VOICE-3', 'Luyện thêm: Active or passive?', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: The windows ______ broken last night. (past passive)', NULL, NULL, NULL, NULL, ARRAY['were'], 'Windows is plural, so the past passive uses were.', NULL, 'EASY'),
('G55_RELATIVE_CLAUSES', 'WRITING', 'DEMO-PS-G55_RELATIVE_CLAUSES-2', 'Luyện thêm: Who, that and whose', 1, 'MULTIPLE_CHOICE', 'The woman ______ lives next door is a doctor.', 'who', 'which', 'where', 'A', NULL, 'Who refers to a person.', NULL, 'EASY'),
('G55_RELATIVE_CLAUSES', 'WRITING', 'DEMO-PS-G55_RELATIVE_CLAUSES-2', 'Luyện thêm: Who, that and whose', 2, 'MULTIPLE_CHOICE', 'This is the book ______ I told you about.', 'who', 'that', 'where', 'B', NULL, 'That refers to a thing.', NULL, 'EASY'),
('G55_RELATIVE_CLAUSES', 'WRITING', 'DEMO-PS-G55_RELATIVE_CLAUSES-2', 'Luyện thêm: Who, that and whose', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: The man ______ car was stolen called the police.', NULL, NULL, NULL, NULL, ARRAY['whose'], 'Whose shows possession: the man''s car.', NULL, 'EASY'),
('G55_RELATIVE_CLAUSES', 'WRITING', 'DEMO-PS-G55_RELATIVE_CLAUSES-3', 'Luyện thêm: Where and which', 1, 'MULTIPLE_CHOICE', 'The city ______ I was born is very old.', 'who', 'which', 'where', 'C', NULL, 'Where refers to a place.', NULL, 'EASY'),
('G55_RELATIVE_CLAUSES', 'WRITING', 'DEMO-PS-G55_RELATIVE_CLAUSES-3', 'Luyện thêm: Where and which', 2, 'MULTIPLE_CHOICE', 'Students ______ work hard usually succeed.', 'who', 'whose', 'whom', 'A', NULL, 'Who is the subject of work.', NULL, 'EASY'),
('G55_RELATIVE_CLAUSES', 'WRITING', 'DEMO-PS-G55_RELATIVE_CLAUSES-3', 'Luyện thêm: Where and which', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: The film ______ we watched last night was boring.', NULL, NULL, NULL, NULL, ARRAY['that', 'which'], 'That or which can refer to a thing.', NULL, 'EASY'),
('L40_DAILY_SCHEDULE', 'LISTENING', 'DEMO-PS-L40_DAILY_SCHEDULE-2', 'Luyện thêm: Class and lunch times', 1, 'MULTIPLE_CHOICE', 'You hear: "The art class starts at a quarter past nine and finishes at half past ten." When does the class finish?', '9:15', '10:30', '9:30', 'B', NULL, 'Half past ten is 10:30. A quarter past nine, 9:15, is when the class starts.', 'Ghi giờ kết thúc, không phải giờ bắt đầu.', 'EASY'),
('L40_DAILY_SCHEDULE', 'LISTENING', 'DEMO-PS-L40_DAILY_SCHEDULE-2', 'Luyện thêm: Class and lunch times', 2, 'MULTIPLE_CHOICE', 'You hear: "Lunch is from twelve forty-five to one thirty." How long is lunch?', '30 minutes', '1 hour 15 minutes', '45 minutes', 'C', NULL, 'From 12:45 to 1:30 is forty-five minutes.', NULL, 'EASY'),
('L40_DAILY_SCHEDULE', 'LISTENING', 'DEMO-PS-L40_DAILY_SCHEDULE-2', 'Luyện thêm: Class and lunch times', 3, 'FILL_IN_BLANK', 'You hear: "The film begins at seven fifteen." Write the start time in numbers (hour:minutes).', NULL, NULL, NULL, NULL, ARRAY['7:15', '7.15', '7 15', '07:15'], 'Seven fifteen is written 7:15.', NULL, 'EASY'),
('L40_DAILY_SCHEDULE', 'LISTENING', 'DEMO-PS-L40_DAILY_SCHEDULE-3', 'Luyện thêm: Opening hours and buses', 1, 'MULTIPLE_CHOICE', 'You hear: "The gym opens at six in the morning and closes at ten at night." When does the gym close?', '10 p.m.', '6 a.m.', '10 a.m.', 'A', NULL, 'Ten at night is 10 p.m. Six in the morning is when it opens.', NULL, 'EASY'),
('L40_DAILY_SCHEDULE', 'LISTENING', 'DEMO-PS-L40_DAILY_SCHEDULE-3', 'Luyện thêm: Opening hours and buses', 2, 'MULTIPLE_CHOICE', 'You hear: "Our first lesson is at eight twenty, and the second lesson starts forty minutes later." When does the second lesson start?', '8:40', '9:00', '9:20', 'B', NULL, '8:20 plus forty minutes is 9:00.', NULL, 'EASY'),
('L40_DAILY_SCHEDULE', 'LISTENING', 'DEMO-PS-L40_DAILY_SCHEDULE-3', 'Luyện thêm: Opening hours and buses', 3, 'FILL_IN_BLANK', 'You hear: "The bus leaves at five to three." Write the time in numbers (hour:minutes).', NULL, NULL, NULL, NULL, ARRAY['2:55', '2.55', '02:55'], 'Five to three means five minutes before three, which is 2:55.', 'Năm phút trước ba giờ.', 'EASY'),
('L40_MAIN_POINT', 'LISTENING', 'DEMO-PS-L40_MAIN_POINT-2', 'Luyện thêm: Why are they speaking?', 1, 'MULTIPLE_CHOICE', 'You hear: "Hello, this is Mr Brown from the garage. Your car is ready, so you can pick it up after two o''clock." Why is he calling?', 'To ask for money', 'To cancel an appointment', 'To say the car is ready', 'C', NULL, 'He says the car is ready and can be collected.', NULL, 'EASY'),
('L40_MAIN_POINT', 'LISTENING', 'DEMO-PS-L40_MAIN_POINT-2', 'Luyện thêm: Why are they speaking?', 2, 'MULTIPLE_CHOICE', 'You hear: "Excuse me, could you tell me where the post office is?" What does the speaker want?', 'To find out where the post office is', 'To order a taxi', 'To book a table', 'A', NULL, 'The speaker asks for the location of the post office.', NULL, 'EASY'),
('L40_MAIN_POINT', 'LISTENING', 'DEMO-PS-L40_MAIN_POINT-2', 'Luyện thêm: Why are they speaking?', 3, 'FILL_IN_BLANK', 'You hear: "Attention please. The nine-forty train to Leeds is cancelled." Complete with ONE WORD: The train to Leeds is ______.', NULL, NULL, NULL, NULL, ARRAY['cancelled', 'canceled'], 'The announcement says the train is cancelled.', NULL, 'EASY'),
('L40_MAIN_POINT', 'LISTENING', 'DEMO-PS-L40_MAIN_POINT-3', 'Luyện thêm: Invitations and instructions', 1, 'MULTIPLE_CHOICE', 'You hear: "Hi Sara, it''s Tom. Are you free on Saturday? I''d like to invite you to my birthday party." Why is Tom calling?', 'To ask Sara for help with homework', 'To invite Sara to a party', 'To say sorry for being late', 'B', NULL, 'Tom asks Sara to come to his birthday party.', NULL, 'EASY'),
('L40_MAIN_POINT', 'LISTENING', 'DEMO-PS-L40_MAIN_POINT-3', 'Luyện thêm: Invitations and instructions', 2, 'MULTIPLE_CHOICE', 'You hear: "Good morning, class. Please open your books at page twenty." What is the teacher asking the students to do?', 'Close the door', 'Write their names', 'Open their books', 'C', NULL, 'The teacher tells the students to open their books at page twenty.', NULL, 'EASY'),
('L40_MAIN_POINT', 'LISTENING', 'DEMO-PS-L40_MAIN_POINT-3', 'Luyện thêm: Invitations and instructions', 3, 'FILL_IN_BLANK', 'You hear: "Customers, the shop will close in ten minutes." Complete with ONE WORD: The speaker is making an ______.', NULL, NULL, NULL, NULL, ARRAY['announcement'], 'A message to everyone in a shop is an announcement.', NULL, 'EASY'),
('L40_PHONE_NUMBERS', 'LISTENING', 'DEMO-PS-L40_PHONE_NUMBERS-2', 'Luyện thêm: Phone numbers and prices', 1, 'MULTIPLE_CHOICE', 'You hear: "My number is oh seven nine, four double five, one two three." Which is correct?', '079 455 123', '079 545 123', '097 455 123', 'A', NULL, 'Double five means two fives: 079 455 123.', 'Double five là hai số 5.', 'EASY'),
('L40_PHONE_NUMBERS', 'LISTENING', 'DEMO-PS-L40_PHONE_NUMBERS-2', 'Luyện thêm: Phone numbers and prices', 2, 'MULTIPLE_CHOICE', 'You hear: "The ticket costs fifteen pounds fifty." What is the price?', '£50.15', '£15.50', '£15.05', 'B', NULL, 'Fifteen pounds fifty is £15.50.', NULL, 'EASY'),
('L40_PHONE_NUMBERS', 'LISTENING', 'DEMO-PS-L40_PHONE_NUMBERS-2', 'Luyện thêm: Phone numbers and prices', 3, 'FILL_IN_BLANK', 'You hear: "My locker code is three, three, six, one." Write the code in numbers.', NULL, NULL, NULL, NULL, ARRAY['3361', '3 3 6 1'], 'The four digits are 3, 3, 6 and 1.', NULL, 'EASY'),
('L40_PHONE_NUMBERS', 'LISTENING', 'DEMO-PS-L40_PHONE_NUMBERS-3', 'Luyện thêm: House numbers and large numbers', 1, 'MULTIPLE_CHOICE', 'You hear: "The shop is at number thirteen, not thirty." Which number is the shop?', '30', '3', '13', 'C', NULL, 'The speaker corrects thirty to thirteen.', 'Thirteen và thirty dễ nghe nhầm.', 'EASY'),
('L40_PHONE_NUMBERS', 'LISTENING', 'DEMO-PS-L40_PHONE_NUMBERS-3', 'Luyện thêm: House numbers and large numbers', 2, 'MULTIPLE_CHOICE', 'You hear: "The room costs one hundred and twenty dollars." What is the price?', '$120', '$12', '$1,200', 'A', NULL, 'One hundred and twenty is 120.', NULL, 'EASY'),
('L40_PHONE_NUMBERS', 'LISTENING', 'DEMO-PS-L40_PHONE_NUMBERS-3', 'Luyện thêm: House numbers and large numbers', 3, 'FILL_IN_BLANK', 'You hear: "My mobile is zero eight, double nine, four." Write the number you hear.', NULL, NULL, NULL, NULL, ARRAY['08994', '0 8 9 9 4'], 'Double nine means two nines: 08994.', NULL, 'EASY'),
('L40_PLACES_DIRECTIONS', 'LISTENING', 'DEMO-PS-L40_PLACES_DIRECTIONS-2', 'Luyện thêm: Finding places', 1, 'MULTIPLE_CHOICE', 'You hear: "The café is on the left, next to the bank." Where is the café?', 'Opposite the bank, on the right', 'Next to the bank, on the left', 'Behind the bank', 'B', NULL, 'The speaker says on the left and next to the bank.', NULL, 'EASY'),
('L40_PLACES_DIRECTIONS', 'LISTENING', 'DEMO-PS-L40_PLACES_DIRECTIONS-2', 'Luyện thêm: Finding places', 2, 'MULTIPLE_CHOICE', 'You hear: "The library is upstairs, on the second floor." Where is the library?', 'On the ground floor', 'In the basement', 'On the second floor', 'C', NULL, 'Upstairs on the second floor.', NULL, 'EASY'),
('L40_PLACES_DIRECTIONS', 'LISTENING', 'DEMO-PS-L40_PLACES_DIRECTIONS-2', 'Luyện thêm: Finding places', 3, 'FILL_IN_BLANK', 'You hear: "Go straight on and turn right at the traffic lights." Complete with ONE WORD: Turn ______ at the traffic lights.', NULL, NULL, NULL, NULL, ARRAY['right'], 'The speaker says turn right.', NULL, 'EASY'),
('L40_PLACES_DIRECTIONS', 'LISTENING', 'DEMO-PS-L40_PLACES_DIRECTIONS-3', 'Luyện thêm: Meeting points', 1, 'MULTIPLE_CHOICE', 'You hear: "Meet me in front of the cinema, not inside." Where will they meet?', 'Outside the cinema', 'Inside the cinema', 'Behind the cinema', 'A', NULL, 'In front of the cinema means outside it.', NULL, 'EASY'),
('L40_PLACES_DIRECTIONS', 'LISTENING', 'DEMO-PS-L40_PLACES_DIRECTIONS-3', 'Luyện thêm: Meeting points', 2, 'MULTIPLE_CHOICE', 'You hear: "The shoe shop is between the chemist and the bakery." Where is the shoe shop?', 'Opposite the chemist', 'Between the chemist and the bakery', 'Next to the post office', 'B', NULL, 'Between means in the middle of two places.', NULL, 'EASY'),
('L40_PLACES_DIRECTIONS', 'LISTENING', 'DEMO-PS-L40_PLACES_DIRECTIONS-3', 'Luyện thêm: Meeting points', 3, 'FILL_IN_BLANK', 'You hear: "The exit is straight ahead, at the end of the corridor." Complete with ONE WORD: The exit is at the ______ of the corridor.', NULL, NULL, NULL, NULL, ARRAY['end'], 'The speaker says at the end of the corridor.', NULL, 'EASY'),
('L50_EVERYDAY_CONVERSATION', 'LISTENING', 'DEMO-PS-L50_EVERYDAY_CONVERSATION-2', 'Luyện thêm: Booking a table', 1, 'MULTIPLE_CHOICE', 'You hear: "I''d like to book a table for four people on Saturday at seven. Actually, could we make it half past seven?" What time is the final booking?', '7:00', '8:30', '7:30', 'C', NULL, 'The speaker changes seven to half past seven, so the final time is 7:30.', 'Người nói đổi ý: lấy giờ cuối.', 'EASY'),
('L50_EVERYDAY_CONVERSATION', 'LISTENING', 'DEMO-PS-L50_EVERYDAY_CONVERSATION-2', 'Luyện thêm: Booking a table', 2, 'MULTIPLE_CHOICE', 'You hear: "I''d like to book a table for four people on Saturday at seven..." How many people is the booking for?', 'Four', 'Six', 'Seven', 'A', NULL, 'The booking is for four people.', NULL, 'EASY'),
('L50_EVERYDAY_CONVERSATION', 'LISTENING', 'DEMO-PS-L50_EVERYDAY_CONVERSATION-2', 'Luyện thêm: Booking a table', 3, 'FILL_IN_BLANK', 'You hear: "I''d like to book a table for four people on Saturday..." Which day is the booking?', NULL, NULL, NULL, NULL, ARRAY['saturday'], 'The booking is for Saturday.', NULL, 'EASY'),
