('R55_READ_SHORT_TEXTS', 'READING', 'DEMO-PS-R55_READ_SHORT_TEXTS-3', 'Luyện thêm: About tea', 2, 'MULTIPLE_CHOICE', 'Text: "...It was first made in China thousands of years ago..." Where was tea first made?', 'In India', 'In Britain', 'In China', 'C', NULL, 'The text says tea was first made in China.', NULL, 'EASY'),
('R55_READ_SHORT_TEXTS', 'READING', 'DEMO-PS-R55_READ_SHORT_TEXTS-3', 'Luyện thêm: About tea', 3, 'FILL_IN_BLANK', 'Text: "...people drink it hot or cold in almost every country." Complete with ONE WORD: Tea can be drunk hot or ______.', NULL, NULL, NULL, NULL, ARRAY['cold'], 'People drink it hot or cold.', NULL, 'EASY'),
('V55_ACADEMIC_COLLOCATIONS', 'WRITING', 'DEMO-PS-V55_ACADEMIC_COLLOCATIONS-2', 'Luyện thêm: Verb and noun partners', 1, 'MULTIPLE_CHOICE', 'Researchers ______ a survey of 500 students.', 'carried out', 'did out', 'took out', 'A', NULL, 'The natural collocation is carry out a survey.', NULL, 'EASY'),
('V55_ACADEMIC_COLLOCATIONS', 'WRITING', 'DEMO-PS-V55_ACADEMIC_COLLOCATIONS-2', 'Luyện thêm: Verb and noun partners', 2, 'MULTIPLE_CHOICE', 'The government must ______ action to reduce pollution.', 'make', 'take', 'do', 'B', NULL, 'We take action.', NULL, 'EASY'),
('V55_ACADEMIC_COLLOCATIONS', 'WRITING', 'DEMO-PS-V55_ACADEMIC_COLLOCATIONS-2', 'Luyện thêm: Verb and noun partners', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: Education plays an important ______ in society.', NULL, NULL, NULL, NULL, ARRAY['role'], 'The collocation is play a role.', NULL, 'EASY'),
