('V55_ACADEMIC_COLLOCATIONS', 'WRITING', 'DEMO-PS-V55_ACADEMIC_COLLOCATIONS-3', 'Luyện thêm: Change and belief', 2, 'MULTIPLE_CHOICE', 'Many people ______ the view that technology has improved life.', 'hold', 'carry', 'bring', 'A', NULL, 'We say hold the view that.', NULL, 'EASY'),
('V55_ACADEMIC_COLLOCATIONS', 'WRITING', 'DEMO-PS-V55_ACADEMIC_COLLOCATIONS-3', 'Luyện thêm: Change and belief', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: It is widely ______ that exercise improves health.', NULL, NULL, NULL, NULL, ARRAY['believed', 'accepted', 'known', 'thought', 'agreed'], 'It is widely believed/accepted that... is a common academic pattern.', NULL, 'EASY'),
('V55_BASIC_WORDS', 'WRITING', 'DEMO-PS-V55_BASIC_WORDS-2', 'Luyện thêm: People and places', 1, 'MULTIPLE_CHOICE', 'Which word means the person who teaches students at school?', 'doctor', 'teacher', 'driver', 'B', NULL, 'A teacher works in a school. A doctor treats patients and a driver drives vehicles.', NULL, 'EASY'),
('V55_BASIC_WORDS', 'WRITING', 'DEMO-PS-V55_BASIC_WORDS-2', 'Luyện thêm: People and places', 2, 'MULTIPLE_CHOICE', 'Where do you usually buy bread and milk?', 'At a hospital', 'At a library', 'At a supermarket', 'C', NULL, 'A supermarket sells food. A hospital treats people and a library lends books.', NULL, 'EASY'),
('V55_BASIC_WORDS', 'WRITING', 'DEMO-PS-V55_BASIC_WORDS-2', 'Luyện thêm: People and places', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: A person who works in a hospital and helps sick people is a ______.', NULL, NULL, NULL, NULL, ARRAY['doctor', 'nurse'], 'Doctors and nurses both work in hospitals and help sick people.', NULL, 'EASY'),
('V55_BASIC_WORDS', 'WRITING', 'DEMO-PS-V55_BASIC_WORDS-3', 'Luyện thêm: Time and actions', 1, 'MULTIPLE_CHOICE', 'Which word is a day of the week?', 'Thursday', 'December', 'morning', 'A', NULL, 'Thursday is a day. December is a month and morning is a part of the day.', NULL, 'EASY'),
('V55_BASIC_WORDS', 'WRITING', 'DEMO-PS-V55_BASIC_WORDS-3', 'Luyện thêm: Time and actions', 2, 'MULTIPLE_CHOICE', 'Which word means to go from one place to another by car, bus or train?', 'borrow', 'travel', 'cook', 'B', NULL, 'Travel means to go from place to place. Borrow and cook have different meanings.', NULL, 'EASY'),
('V55_BASIC_WORDS', 'WRITING', 'DEMO-PS-V55_BASIC_WORDS-3', 'Luyện thêm: Time and actions', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: We eat breakfast in the ______, before we go to work.', NULL, NULL, NULL, NULL, ARRAY['morning'], 'Breakfast is the first meal, eaten in the morning.', NULL, 'EASY'),
('V55_COMMON_TOPICS', 'WRITING', 'DEMO-PS-V55_COMMON_TOPICS-2', 'Luyện thêm: Environment, health and education', 1, 'MULTIPLE_CHOICE', 'Global warming is a major ______ issue.', 'environment', 'environ', 'environmental', 'C', NULL, 'An adjective is needed before issue: environmental.', NULL, 'EASY'),
('V55_COMMON_TOPICS', 'WRITING', 'DEMO-PS-V55_COMMON_TOPICS-2', 'Luyện thêm: Environment, health and education', 2, 'MULTIPLE_CHOICE', 'Which word belongs to the topic of health?', 'diet', 'tourist', 'salary', 'A', NULL, 'Diet is about what we eat and our health.', NULL, 'EASY'),
('V55_COMMON_TOPICS', 'WRITING', 'DEMO-PS-V55_COMMON_TOPICS-2', 'Luyện thêm: Environment, health and education', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: Students pay tuition ______ to the university.', NULL, NULL, NULL, NULL, ARRAY['fees', 'fee'], 'Tuition fees are what students pay for teaching.', NULL, 'EASY'),
('V55_COMMON_TOPICS', 'WRITING', 'DEMO-PS-V55_COMMON_TOPICS-3', 'Luyện thêm: Transport and the environment', 1, 'MULTIPLE_CHOICE', 'Which word belongs to the topic of transport?', 'scientist', 'commuter', 'vitamin', 'B', NULL, 'A commuter travels regularly to work.', NULL, 'EASY'),
('V55_COMMON_TOPICS', 'WRITING', 'DEMO-PS-V55_COMMON_TOPICS-3', 'Luyện thêm: Transport and the environment', 2, 'MULTIPLE_CHOICE', 'Many people use public ______ to avoid traffic.', 'transfer', 'travelling', 'transport', 'C', NULL, 'Public transport is the usual collocation.', NULL, 'EASY'),
('V55_COMMON_TOPICS', 'WRITING', 'DEMO-PS-V55_COMMON_TOPICS-3', 'Luyện thêm: Transport and the environment', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: Recycling helps to reduce ______.', NULL, NULL, NULL, NULL, ARRAY['waste', 'pollution'], 'Recycling reduces waste and pollution.', NULL, 'EASY'),
('V55_PARAPHRASE_WORDS', 'WRITING', 'DEMO-PS-V55_PARAPHRASE_WORDS-2', 'Luyện thêm: Common words', 1, 'MULTIPLE_CHOICE', 'Which word is closest in meaning to "big" in "a big increase"?', 'large', 'heavy', 'wide', 'A', NULL, 'A large increase means a big increase.', NULL, 'EASY'),
('V55_PARAPHRASE_WORDS', 'WRITING', 'DEMO-PS-V55_PARAPHRASE_WORDS-2', 'Luyện thêm: Common words', 2, 'MULTIPLE_CHOICE', 'Which word can replace "buy"?', 'pay', 'purchase', 'sell', 'B', NULL, 'Purchase means buy.', NULL, 'EASY'),
('V55_PARAPHRASE_WORDS', 'WRITING', 'DEMO-PS-V55_PARAPHRASE_WORDS-2', 'Luyện thêm: Common words', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: "help" can be paraphrased as "______".', NULL, NULL, NULL, NULL, ARRAY['assist', 'support', 'aid'], 'Assist, support and aid all keep the meaning of help.', NULL, 'EASY'),
('V55_PARAPHRASE_WORDS', 'WRITING', 'DEMO-PS-V55_PARAPHRASE_WORDS-3', 'Luyện thêm: Verbs and adjectives', 1, 'MULTIPLE_CHOICE', 'Which word can replace "start"?', 'finish', 'stay', 'begin', 'C', NULL, 'Begin means start.', NULL, 'EASY'),
