('V55_PARAPHRASE_WORDS', 'WRITING', 'DEMO-PS-V55_PARAPHRASE_WORDS-3', 'Luyện thêm: Verbs and adjectives', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: "show" can be paraphrased as "______".', NULL, NULL, NULL, NULL, ARRAY['demonstrate', 'indicate', 'display', 'illustrate', 'reveal'], 'Demonstrate, indicate, illustrate and reveal can replace show.', NULL, 'EASY'),
('V55_WORD_FORMS', 'WRITING', 'DEMO-PS-V55_WORD_FORMS-2', 'Luyện thêm: Adjective and adverb', 1, 'MULTIPLE_CHOICE', 'She is a very ______ driver. (care)', 'care', 'careful', 'carefully', 'B', NULL, 'An adjective is needed before a noun: careful driver.', NULL, 'EASY'),
('V55_WORD_FORMS', 'WRITING', 'DEMO-PS-V55_WORD_FORMS-2', 'Luyện thêm: Adjective and adverb', 2, 'MULTIPLE_CHOICE', 'He answered the question ______. (quick)', 'quick', 'quickness', 'quickly', 'C', NULL, 'An adverb describes how he answered: quickly.', NULL, 'EASY'),
('V55_WORD_FORMS', 'WRITING', 'DEMO-PS-V55_WORD_FORMS-2', 'Luyện thêm: Adjective and adverb', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: The ______ (decide) to move abroad was difficult.', NULL, NULL, NULL, NULL, ARRAY['decision'], 'A noun is needed after the: decision.', NULL, 'EASY'),
('V55_WORD_FORMS', 'WRITING', 'DEMO-PS-V55_WORD_FORMS-3', 'Luyện thêm: Noun and adverb', 1, 'MULTIPLE_CHOICE', 'There was a lot of ______ between the two reports. (differ)', 'difference', 'different', 'differently', 'A', NULL, 'After a lot of we need a noun: difference.', NULL, 'EASY'),
('V55_WORD_FORMS', 'WRITING', 'DEMO-PS-V55_WORD_FORMS-3', 'Luyện thêm: Noun and adverb', 2, 'MULTIPLE_CHOICE', 'It is ______ to sleep well. (importance)', 'importance', 'important', 'importantly', 'B', NULL, 'After is we need an adjective: important.', NULL, 'EASY'),
('V55_WORD_FORMS', 'WRITING', 'DEMO-PS-V55_WORD_FORMS-3', 'Luyện thêm: Noun and adverb', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: The company grew ______ last year. (rapid)', NULL, NULL, NULL, NULL, ARRAY['rapidly'], 'An adverb describes the verb grew: rapidly.', NULL, 'EASY'),
('W40_SHORT_MESSAGE', 'WRITING', 'DEMO-PS-W40_SHORT_MESSAGE-2', 'Luyện thêm: Opening and purpose', 1, 'MULTIPLE_CHOICE', 'Which opening is best for a message to a friend?', 'To whom it may concern,', 'Dear Sir or Madam,', 'Hi Sam,', 'C', NULL, 'Hi is friendly and suits a friend.', NULL, 'EASY'),
('W40_SHORT_MESSAGE', 'WRITING', 'DEMO-PS-W40_SHORT_MESSAGE-2', 'Luyện thêm: Opening and purpose', 2, 'MULTIPLE_CHOICE', 'Which sentence gives the purpose clearly?', 'I''m writing to ask if you can come on Friday.', 'Friday is a day of the week.', 'The weather is nice.', 'A', NULL, 'It says why you are writing.', NULL, 'EASY'),
('W40_SHORT_MESSAGE', 'WRITING', 'DEMO-PS-W40_SHORT_MESSAGE-2', 'Luyện thêm: Opening and purpose', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: A polite ending is "See you ______!"', NULL, NULL, NULL, NULL, ARRAY['soon'], 'See you soon is a friendly ending.', NULL, 'EASY'),
('W40_SHORT_MESSAGE', 'WRITING', 'DEMO-PS-W40_SHORT_MESSAGE-3', 'Luyện thêm: Polite endings', 1, 'MULTIPLE_CHOICE', 'Which ending is polite and friendly?', 'Answer me now. Lena', 'Thanks for your help. Best wishes, Lena', 'Nothing else. Lena', 'B', NULL, 'It thanks the reader and closes politely.', NULL, 'EASY'),
('W40_SHORT_MESSAGE', 'WRITING', 'DEMO-PS-W40_SHORT_MESSAGE-3', 'Luyện thêm: Polite endings', 2, 'MULTIPLE_CHOICE', 'A short message to a teacher should start with:', 'Hey you,', 'Mr Hall!!!', 'Dear Mr Hall,', 'C', NULL, 'Dear + name is polite for a teacher.', NULL, 'EASY'),
('W40_SHORT_MESSAGE', 'WRITING', 'DEMO-PS-W40_SHORT_MESSAGE-3', 'Luyện thêm: Polite endings', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: "I am writing ______ say sorry for being late."', NULL, NULL, NULL, NULL, ARRAY['to'], 'I am writing to + verb gives the purpose.', NULL, 'EASY'),
('W50_EMAIL', 'WRITING', 'DEMO-PS-W50_EMAIL-2', 'Luyện thêm: Informal openings and reasons', 1, 'MULTIPLE_CHOICE', 'Which opening is suitable for an email to a friend?', 'Hi Jo, How are you?', 'Dear Sir or Madam,', 'To the manager,', 'A', NULL, 'Hi + first name is friendly and informal.', NULL, 'EASY'),
('W50_EMAIL', 'WRITING', 'DEMO-PS-W50_EMAIL-2', 'Luyện thêm: Informal openings and reasons', 2, 'MULTIPLE_CHOICE', 'Which sentence gives the reason for writing?', 'Holidays are popular.', 'I''m writing to ask for your advice about my holiday.', 'It is Monday today.', 'B', NULL, 'It says clearly why you are writing.', NULL, 'EASY'),
('W50_EMAIL', 'WRITING', 'DEMO-PS-W50_EMAIL-2', 'Luyện thêm: Informal openings and reasons', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: A friendly ending is "Write back ______!"', NULL, NULL, NULL, NULL, ARRAY['soon'], 'Write back soon is a common friendly ending.', NULL, 'EASY'),
('W50_EMAIL', 'WRITING', 'DEMO-PS-W50_EMAIL-3', 'Luyện thêm: Informal style and endings', 1, 'MULTIPLE_CHOICE', 'Which ending is best for an informal email?', 'Yours faithfully, Mia Hill', 'Regards, The Applicant', 'Hope to hear from you soon. Take care, Mia', 'C', NULL, 'It is warm and friendly.', NULL, 'EASY'),
('W50_EMAIL', 'WRITING', 'DEMO-PS-W50_EMAIL-3', 'Luyện thêm: Informal style and endings', 2, 'MULTIPLE_CHOICE', 'In an informal email you can use:', 'Contractions such as I''m and don''t', 'Only very long sentences', 'No greeting at all', 'A', NULL, 'Contractions are natural in friendly writing.', NULL, 'EASY'),
('W50_EMAIL', 'WRITING', 'DEMO-PS-W50_EMAIL-3', 'Luyện thêm: Informal style and endings', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: Ask a question: "Would you like to come with ______?"', NULL, NULL, NULL, NULL, ARRAY['us', 'me'], 'Object pronouns us or me fit here.', NULL, 'EASY'),
('W50_OPINION_PARAGRAPH', 'WRITING', 'DEMO-PS-W50_OPINION_PARAGRAPH-2', 'Luyện thêm: Topic sentence and reasons', 1, 'MULTIPLE_CHOICE', 'Which topic sentence states an opinion?', 'Public transport has buses and trains.', 'I believe that public transport should be free.', 'Many cities have buses.', 'B', NULL, 'I believe that... states a personal opinion.', NULL, 'EASY'),
('W50_OPINION_PARAGRAPH', 'WRITING', 'DEMO-PS-W50_OPINION_PARAGRAPH-2', 'Luyện thêm: Topic sentence and reasons', 2, 'MULTIPLE_CHOICE', 'A good opinion paragraph gives:', 'Ten short reasons', 'No reasons', 'Two reasons with examples', 'C', NULL, 'A clear opinion needs reasons supported by examples.', NULL, 'EASY'),
('W50_OPINION_PARAGRAPH', 'WRITING', 'DEMO-PS-W50_OPINION_PARAGRAPH-2', 'Luyện thêm: Topic sentence and reasons', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: Restate your opinion in the last sentence to ______ the paragraph.', NULL, NULL, NULL, NULL, ARRAY['conclude', 'end', 'finish', 'close'], 'The last sentence concludes the paragraph.', NULL, 'EASY'),
('W50_OPINION_PARAGRAPH', 'WRITING', 'DEMO-PS-W50_OPINION_PARAGRAPH-3', 'Luyện thêm: Linking reasons', 1, 'MULTIPLE_CHOICE', 'Which phrase introduces a reason?', 'This is because', 'On the other hand', 'In contrast', 'A', NULL, 'This is because introduces a reason.', NULL, 'EASY'),
('W50_OPINION_PARAGRAPH', 'WRITING', 'DEMO-PS-W50_OPINION_PARAGRAPH-3', 'Luyện thêm: Linking reasons', 2, 'MULTIPLE_CHOICE', 'Which is a suitable ending?', 'Homework is a word.', 'For these reasons, I strongly believe that homework should be limited.', 'My teacher gives homework.', 'B', NULL, 'It restates the opinion and links to the reasons.', NULL, 'EASY'),
('W50_OPINION_PARAGRAPH', 'WRITING', 'DEMO-PS-W50_OPINION_PARAGRAPH-3', 'Luyện thêm: Linking reasons', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: "In my ______, school uniforms are a good idea."', NULL, NULL, NULL, NULL, ARRAY['opinion', 'view'], 'In my opinion/view introduces a personal opinion.', NULL, 'EASY'),
('W50_SIMPLE_CHART', 'WRITING', 'DEMO-PS-W50_SIMPLE_CHART-2', 'Luyện thêm: Bar chart of museum visitors', 1, 'MULTIPLE_CHOICE', 'A bar chart shows visitors to a museum: Monday 120, Tuesday 90, Wednesday 150, Thursday 110. Which day had the highest number of visitors?', 'Monday', 'Tuesday', 'Wednesday', 'C', NULL, 'Wednesday at 150 is the highest figure.', NULL, 'EASY'),
('W50_SIMPLE_CHART', 'WRITING', 'DEMO-PS-W50_SIMPLE_CHART-2', 'Luyện thêm: Bar chart of museum visitors', 2, 'MULTIPLE_CHOICE', 'A bar chart shows visitors to a museum: Monday 120, Tuesday 90, Wednesday 150, Thursday 110. Which sentence compares two days correctly?', 'Wednesday had more visitors than Tuesday.', 'Tuesday had more visitors than Wednesday.', 'Monday had fewer visitors than Tuesday.', 'A', NULL, '150 is more than 90, so Wednesday had more visitors than Tuesday.', NULL, 'EASY'),
('W50_SIMPLE_CHART', 'WRITING', 'DEMO-PS-W50_SIMPLE_CHART-2', 'Luyện thêm: Bar chart of museum visitors', 3, 'FILL_IN_BLANK', 'Complete with ONE WORD: The chart shows the ______ of visitors to a museum.', NULL, NULL, NULL, NULL, ARRAY['number'], 'Visitors are counted, so we say the number of visitors.', NULL, 'EASY'),
